/**/

function setup() {
  createCanvas( 1024, 768 );
  background( 0 );
  mousePressed( 0, 0 );
}

function draw() {
  background( 0, 10 );
  j = 0;
  while(++j<num) {
    target = pos[j];
    target.aX *= .98;
    target.aY *= .98;

    oldX = target.x;
    oldY = target.y;
    target.x += target.aX;
    target.y += target.aY + 1;

    target.d *= .98;
    w = target.d*5;
    i = 0;

    while(i++<5) {
      base = 50/i;
      push();
      blendMode(ADD);
      stroke( base + (1-target.d)*100, base+50, base + target.d*250, base );
      strokeWeight( w*=1.5 );
      line( target.x, target.y, oldX, oldY );
      pop();
    }
  }

	let delay = random(60, 100);
	if (frameCount%delay < 1){
		window.simulatedMouseX = random(32, width - 32);
		window.simulatedMouseY = random(24, height - 24);
		mousePressed();
	}
}

function mousePressed(e, setD=1) {
  pos = [];
  num = 100;
  speed = 10;
  m = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  n = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  i = 0;
  while(++i<num) {
    pos[i] = {
      x: m,
      y: n,
      aX: random(-speed, speed),
      aY: random(-speed, speed),
      d: random(setD*.5, setD)
    }
  }
}
/**/

